import{c as a,Q as l,j as i,m as d}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"索引文件结构","description":"","frontmatter":{"title":"索引文件结构"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/索引文件结构.md","filePath":"综合知识/系统基础/操作系统/索引文件结构.md","lastUpdated":null}'),r={name:"综合知识/系统基础/操作系统/索引文件结构.md"};function s(e,t,o,n,c,p){return l(),i("div",null,[...t[0]||(t[0]=[d('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 直接索引/一级间接索引/二级间接索引</li><li>[x] 索引容量计算</li><li>[x] 逻辑块号定位索引类型</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="索引文件结构" tabindex="-1">索引文件结构 <a class="header-anchor" href="#索引文件结构" aria-label="Permalink to &quot;索引文件结构&quot;">​</a></h3><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/bc65a33c6d2b3c157ad83e140c87cb42_MD5.png" alt="索引文件结构"></p><p>假设 13 个索引节点，物理盘块大小 4KB，每个地址占 4B：</p><table tabindex="0"><thead><tr><th>索引类型</th><th>节点</th><th>原理</th><th>容量</th></tr></thead><tbody><tr><td><strong>直接索引</strong></td><td>0~9</td><td>节点直接存放数据内容</td><td>10 × 4KB = 40KB</td></tr><tr><td><strong>一级间接索引</strong></td><td>10</td><td>节点存放指向物理盘块的地址，共 1024 个地址</td><td>1024 × 4KB = 4096KB</td></tr><tr><td><strong>二级间接索引</strong></td><td>11~12</td><td>节点→一级地址块→物理盘块</td><td>1024 × 1024 × 4KB</td></tr></tbody></table><h3 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h3><p>设文件索引节点有 8 个地址项（每项 4 字节）：5 个直接地址索引，2 个一级间接索引，1 个二级间接索引。磁盘索引块和数据块大小均为 1KB。</p><p><strong>Q1</strong>：访问逻辑块号 5 和 518，分别采用什么索引？</p><p>答案：<strong>一级间接地址索引和二级间接地址索引</strong></p><p>解析：</p><ul><li>直接索引：0~4（5 个）</li><li>一级间接索引：每节点 1KB/4B=256 个块，2 个节点覆盖 5~516</li><li>二级间接索引：517 以上</li><li>逻辑块 5 在 5~516 范围 → 一级间接；518 &gt; 516 → 二级间接</li></ul><p><strong>Q2</strong>：单个文件最大长度是多少 KB？</p><p>答案：<strong>66053 KB</strong></p><p>解析：5（直接） + 256×2（一级间接，2个节点各256块） + 256×256（二级间接，256个一级节点各256块）= 5 + 512 + 65536 = 66053 KB</p><h2 id="练习题-1" tabindex="-1">练习题 <a class="header-anchor" href="#练习题-1" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q18] 索引节点-地址计算</strong></p><p>假设文件系统采用索引节点管理，且索引节点有8个地址项iaddr[0]～iaddr[7]，每个地址项大小为4字节，iaddr[0]～iaddr[4]采用直接地址索引，iaddr[5]和iaddr[6]采用一级间接地址索引，iaddr[7]采用二级间接地址索引。假设磁盘索引块和磁盘数据块大小均为1KB字节。若用户访问文件File1中逻辑块号为5和261的信息，则对应的物理块号分别为（ ）。</p><ul><li>A. 89和90</li><li>B. 89和136</li><li>C. 58和187</li><li>D. 90和136</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：直接索引0~4(5块)覆盖逻辑块0~4；一级间接=256块/节点。逻辑块5→iaddr[5]一级间接第0项→58；逻辑块261→261-5=256→iaddr[6]一级间接第0项→187。</p></div></details><hr><p><strong>[Q19] 索引节点-间接索引</strong></p><p>同上题条件。101号物理块存放的是（ ）。</p><ul><li>A. File1的信息</li><li>B. 直接地址索引表</li><li>C. 一级地址索引表</li><li>D. 二级地址索引表</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：iaddr[7]二级间接→先读一级索引块→再读二级索引块。101号块是二级地址索引表。</p></div></details>',26)])])}const _=a(r,[["render",s]]);export{u as __pageData,_ as default};
